
const pl=(t,c='')=>`<span class="pl ${c}">${t}</span>`,cv=(h,b)=>`<div class=card><h3>${h}</h3>${b}</div>`,ch=t=>`<button class=pl onmousedown="event.preventDefault()" onclick="ins('${t}')">${t}</button>`,rw=(a,b)=>`<div class=rw><span>${a}</span><b>${b}</b></div>`;
function subst(f,x,t){switch(f.t){case'P':return{...f,a:f.a.map(a=>substS(a,x,t))};case'q':return f.v==x?f:{...f,a:subst(f.a,x,t)};case'n':return{...f,a:subst(f.a,x,t)};case'v':return f}return{...f,l:subst(f.l,x,t),r:subst(f.r,x,t)}}
const targs=(f,s=new Set)=>{if(f.t=='P')f.a.forEach(a=>termsOf(a,s));else if(f.t=='q'||f.t=='n')targs(f.a,s);else if(f.l){targs(f.l,s);targs(f.r,s)}return s};
function mview(M){let h='<div class=row>'+M.dom.map(d=>`<span class=dot>${d}</span>`).join('')+Object.entries(M.c).map(([k,v])=>pl(k+'='+v)).join('')+'</div><div class=g>';for(let k in M.p){let bin=[...M.p[k]].some(t=>t.includes(','));h+=`<div><b>${k}</b>`+(bin?'<table><tr><th>'+M.dom.map(d=>'<th>'+d).join('')+'</tr>'+M.dom.map(x=>'<tr><th>'+x+M.dom.map(y=>'<td class='+(M.p[k].has(x+','+y)?'T>✓':'F>·')).join('')+'</tr>').join('')+'</table>':'<div>'+M.dom.map(d=>`<span class="dot ${M.p[k].has(d)?'T':''}">${d}</span>`).join('')+'</div>')+'</div>'}h+='</div>';for(const k in(M.fn||{}))h+='<div class=row><b>'+k+'</b> '+Object.entries(M.fn[k]).map(([a,v])=>pl(k+'('+a+')='+v)).join('')+'</div>';return h}
function pres(f,M){let v=pev(f,M),h=`<b class=${v?'ok':'no'}>${v?'True':'False'}</b>`;if(f.t=='q')h+='<div class=row>'+M.dom.map(d=>`<span class="dot ${pev(f.a,M,{[f.v]:d})?'T':'F'}">${d}</span>`).join('')+`<span class=mu>${f.v} ↦ ${sh(f.a)}</span></div>`;return h}
