const NDX={prop:[[['p→p∧q','p'],'q'],[['p→(q→r)','p→q','p'],'r'],[['p→q','p→r'],'p→q∧r'],[['p→q'],'p∧r→q∧r'],[['p∨q→r'],'(p→r)∧(q→r)'],[['p∧(q∨r)'],'(p∧q)∨(p∧r)'],[['p→¬q','(¬q∨r)→¬s','p∧t'],'¬s'],[['p∨q→¬p','¬q'],'¬p']],pred:[[['∀x(p(x)→q(x))','p(a)'],'q(a)'],[['∀x p(x)'],'∃x p(x)'],[['∀x(p(x)∧q(x))'],'∀x p(x)'],[['∀x(p(x)→q(x))','∃x p(x)'],'∃x q(x)']]};
const RU={prop:['∧I','∧E','∨I','∨E','→I','→E','¬I','¬E','¬¬E','MT','↔I','↔E','⊤I','⊤E','⊥I','⊥E'],pred:['∧I','∧E','∨I','∨E','→I','→E','¬I','¬E','¬¬E','MT','⊤I','⊤E','⊥I','⊥E','∀E','∀I','∃I','∃E']};
const SC={'∧I':'A , B ⟹ A∧B','∧E':'A∧B ⟹ A','∨I':'A ⟹ A∨B','∨E':'A∨B , A→C , B→C ⟹ C  (or boxes [A…C],[B…C])','→I':'[A…B] ⟹ A→B','→E':'A→B , A ⟹ B','¬I':'[A…X∧¬X] ⟹ ¬A','¬E':'[¬A…X∧¬X] ⟹ A','¬¬E':'¬¬A ⟹ A','⊤I':'A∨¬A ⟹ ⊤','⊤E':'⊤ ⟹ A∨¬A','⊥I':'A∧¬A ⟹ ⊥','⊥E':'⊥ ⟹ A','MT':'A→B , ¬B ⟹ ¬A','↔I':'A→B , B→A ⟹ A↔B','↔E':'A↔B ⟹ A→B  (or A↔B , A ⟹ B)','∀E':'∀xF ⟹ F[t]','∀I':'F[c] c new ⟹ ∀xF','∃I':'F[t] ⟹ ∃xF','∃E':'∃xF,[F[c]…C] ⟹ C'};
function ndLoad(i,c){let X=c||NDX[S.d][((i%NDX[S.d].length)+NDX[S.d].length)%NDX[S.d].length];S.ndi=i;S.nd={P:X[0],G:X[1],L:X[0].map(f=>({f,r:'Premise',n:'',d:0,fx:1})),d:0,res:null,done:0};ndShow()}
function nd(){if(!S.nd||S.nd.pd!=S.d){ndLoad(0);S.nd.pd=S.d}else ndShow()}
function ndShow(){const n=S.nd,pr=S.d=='pred';n.pd=S.d;$('#M').innerHTML=`<div class=card><div class=f>{ ${n.P.join(',  ')} } ⊢ ${n.G}</div>${n.done?'<p class=ok>🎉 Proof complete</p>':''}`+n.L.map((l,i)=>`<div class=ln style="margin-left:${l.d*18}px;${l.r=='Assume'?'border-color:var(--no)':''}"><b>${i+1}</b> <span class=f>${l.f}</span> <i class=mu>${l.r} ${l.n}</i> ${n.res?(n.res[i]===null?'<span class=ok>✓</span>':'<span class=no>✗ '+n.res[i]+'</span>'):''}</div>`).join('')+`<div class=row style="margin-top:8px"><input id=ndf placeholder="formula" style="flex:2"><select id=ndr>${RU[S.d].map(r=>`<option>${r}</option>`).join('')}</select><input id=ndn placeholder="refs 1,2 · 3-5" style="flex:1"></div><div class=row><button class=on onclick="ndAdd()">+ Line</button><button onclick="ndAdd(1)">▢ Assume</button><button onclick="n=S.nd;n.d=Math.max(0,n.d-1);ndShow()">Close box</button><button onclick="ndUndo()">Undo</button><button onclick="ndChk()">Check</button><button onclick="ndHint()">Hint</button></div><div id=hn></div><span class=mu>depth ${n.d}</span></div><div class=row><button onclick="ndLoad(S.ndi-1)">←</button><button onclick="ndLoad(S.ndi+1)">→</button></div><details class=card><summary>Rules</summary><div class=g>${RU[S.d].map(r=>`<div>${pl(r)}<br><span class=mu>${SC[r]}</span></div>`).join('')}</div></details>`;pal()}
function ndAdd(a){const n=S.nd;let f=$('#ndf').value.trim();try{parse(f,S.d=='pred')}catch(e){$('#hn').innerHTML='<span class=no>'+e.message+'</span>';return}n.cb=0;if(a)n.d++;n.L.push({f,r:a?'Assume':$('#ndr').value,n:a?'':$('#ndn').value,d:n.d});n.res=null;ndShow()}
function ndUndo(){const n=S.nd;if(n.cb>0){n.cb--;n.d++;n.res=null}else if(n.L.length&&!n.L[n.L.length-1].fx){n.L.pop();n.d=n.L[n.L.length-1].d;n.res=null}ndShow()}
function ndHint(){const n=S.nd,g=parse(n.G,S.d=='pred'),m={i:'Goal A→B: ▢ assume A, derive B, then →I.',a:'Goal A∧B: prove both, then ∧I.',o:'Goal A∨B: prove one side, ∨I — or use ∨E on a premise.',n:'Goal ¬A: ▢ assume A, reach X∧¬X, then ¬I.',q:g.k=='A'?'Goal ∀x: derive F[c] for a new c, then ∀I.':'Goal ∃x: find a witness t, then ∃I.',v:'Atomic goal: get it from premises with →E, ∧E or ∨E.',P:'Atomic goal: use ∀E on a premise, then →E / ∧E.',e:'Goal A↔B: prove A→B and B→A, then ↔I.'};let ok=S.d=='prop'?!ent(n.P.map(x=>parse(x)),g):'?';$('#hn').innerHTML='<p>💡 '+m[g.t]+(ok===true?' <span class=ok>(derivable)</span>':ok===false?' <span class=no>(NOT derivable)</span>':'')+'</p>'}
function ndChk(){const n=S.nd,pr=S.d=='pred',G=sh(parse(n.G,pr));n.res=n.L.map((_,i)=>ck(n.L,i,pr));n.done=n.res.every(x=>x===null)&&n.L.some(l=>l.d==0&&sh(parse(l.f,pr))==G);ndShow()}
function ck(L,i,pr){const l=L[i];try{const f=parse(l.f,pr),r=l.r;if(r=='Premise')return l.fx?null:'fixed';if(r=='Assume')return null;
const T=(l.n||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>x.split('-').map(Number)),vis=j=>{for(let k=j+1;k<=i;k++)if(L[k].d<L[j].d)return false;return true},
A=x=>{let j=x-1;if(!(j>=0&&j<i)||!vis(j))throw Error('line '+x+' unavailable');return parse(L[j].f,pr)},V=k=>{if(!T[k])throw Error('missing ref');return A(T[k][0])},
R=k=>{if(!T[k]||T[k].length<2)throw Error('use range s-e');let[s,e]=T[k];if(!(s>=1&&e<=i&&s<=e)||L[s-1].r!='Assume'||L[e-1].d!=L[s-1].d||L[i].d>=L[s-1].d)throw Error('need a closed box');for(let q=s;q<e;q++)if(L[q].d<L[s-1].d)throw Error('bad box');return[parse(L[s-1].f,pr),parse(L[e-1].f,pr)]},
eq=(a,b)=>sh(a)==sh(b),mk=(t,l,r)=>({t,l,r}),nt=a=>({t:'n',a}),ct=c=>c.t=='a'&&(eq(c.r,nt(c.l))||eq(c.l,nt(c.r))),
used=s=>{let u=new Set;L.forEach((x,j)=>{if(j<i&&j!=s&&(x.fx||x.r=='Assume'&&vis(j)))targs(parse(x.f,pr),u)});return u};let a,b,x,y,ok=false;
switch(r){case'∧I':ok=eq(f,mk('a',V(0),V(1)));break;case'∧E':a=V(0);ok=a.t=='a'&&(eq(a.l,f)||eq(a.r,f));break;case'∨I':a=V(0);ok=f.t=='o'&&(eq(f.l,a)||eq(f.r,a));break;
case'→E':a=V(0);b=V(1);ok=[[a,b],[b,a]].some(([p,q])=>p.t=='i'&&eq(p.l,q)&&eq(p.r,f));break;case'MT':a=V(0);b=V(1);ok=f.t=='n'&&[[a,b],[b,a]].some(([p,q])=>p.t=='i'&&eq(nt(p.r),q)&&eq(nt(p.l),f));break;
case'⊤I':a=V(0);ok=f.t=='v'&&f.n=='⊤'&&a.t=='o'&&(eq(a.r,nt(a.l))||eq(a.l,nt(a.r)));break;case'⊤E':a=V(0);ok=a.t=='v'&&a.n=='⊤'&&f.t=='o'&&(eq(f.r,nt(f.l))||eq(f.l,nt(f.r)));break;case'⊥I':a=V(0);ok=f.t=='v'&&f.n=='⊥'&&ct(a);break;case'⊥E':a=V(0);ok=a.t=='v'&&a.n=='⊥';break;case'¬¬E':a=V(0);ok=a.t=='n'&&a.a.t=='n'&&eq(a.a.a,f);break;case'↔E':a=V(0);if(!T[1]){ok=a.t=='e'&&f.t=='i'&&(eq(f.l,a.l)&&eq(f.r,a.r)||eq(f.l,a.r)&&eq(f.r,a.l));break}b=V(1);ok=a.t=='e'&&[[a.l,a.r],[a.r,a.l]].some(([p,q])=>eq(b,p)&&eq(f,q));break;
case'↔I':a=V(0);b=V(1);ok=f.t=='e'&&[[a,b],[b,a]].some(([p,q])=>eq(p,mk('i',f.l,f.r))&&eq(q,mk('i',f.r,f.l)));break;
case'→I':[x,y]=R(0);ok=f.t=='i'&&eq(f.l,x)&&eq(f.r,y);break;case'¬I':[x,y]=R(0);ok=f.t=='n'&&eq(f.a,x)&&ct(y);break;case'¬E':[x,y]=R(0);ok=eq(x,nt(f))&&ct(y);break;
case'∨E':{a=V(0);if(T[1]&&T[1].length==1){let p=V(1),q=V(2);ok=a.t=='o'&&p.t=='i'&&q.t=='i'&&[[p,q],[q,p]].some(([u,w])=>eq(a.l,u.l)&&eq(a.r,w.l))&&eq(p.r,f)&&eq(q.r,f)}else{let[x1,y1]=R(1),[x2,y2]=R(2);ok=a.t=='o'&&[[x1,x2],[x2,x1]].some(([p,q])=>eq(a.l,p)&&eq(a.r,q))&&eq(y1,f)&&eq(y2,f)}}break;
case'∀E':a=V(0);ok=a.t=='q'&&a.k=='A'&&[...targs(f)].some(t=>eq(f,subst(a.a,a.v,t)));break;case'∃I':a=V(0);ok=f.t=='q'&&f.k=='E'&&[...targs(a)].some(t=>eq(a,subst(f.a,f.v,t)));break;
case'∀I':a=V(0);ok=f.t=='q'&&f.k=='A'&&[...targs(a)].some(c=>/^\w+$/.test(c)&&eq(a,subst(f.a,f.v,c))&&!used(-1).has(c)&&!targs(f).has(c));break;
case'∃E':a=V(0);[x,y]=R(1);let s=T[1][0]-1,u=used(s);ok=a.t=='q'&&a.k=='E'&&eq(y,f)&&[...targs(x)].some(c=>/^\w+$/.test(c)&&eq(x,subst(a.a,a.v,c))&&!u.has(c)&&!targs(f).has(c)&&!targs(a).has(c));break;default:return'unknown rule'}
return ok?null:'rule does not apply'}catch(e){return e.message}}
// simulator
const TM=[['Modus ponens','(p→q)∧p→q'],['Modus tollens','(p→q)∧¬q→¬p'],['Excluded middle','p∨¬p'],['Contradiction','p∧¬p'],['De Morgan','¬(p∧q)↔¬p∨¬q'],['Contraposition','(p→q)↔(¬q→¬p)'],['Syllogism','(p→q)∧(q→r)→(p→r)'],['Fallacy','(p→q)∧q→p']];
const TQ=[['All S are P','∀x(q(x)→r(x))'],['Some S are P','∃x(q(x)∧r(x))'],['No S is P','¬∃x(q(x)∧r(x))'],['∀∃','∀x∃y p(x,y)'],['∃∀','∃x∀y p(x,y)'],['Symmetric','∀x∀y(p(x,y)→p(y,x))'],['Reflexive','∀x p(x,x)'],['Not all','¬∀x(q(x)→r(x))']];
const MM=['dom=A,B,C; p={(A,B),(B,C)}; q={A,B}; r={B,C}; a=A; b=B; c=C','dom=A,B; p={(A,A),(B,B)}; q={A}; r={A,B}; a=A; b=B','dom=A; p={(A,A)}; q={A}; r={}; a=A'];
const bs=(a,f)=>a.map((t,i)=>`<button onclick="${f}(${i})">${t[0]}</button>`).join('');
function sim(){$('#M').innerHTML=S.d=='prop'?`<div class=card><h3>Formula</h3><input id=sf placeholder="(p→q)∧p→q"><div class=row>${[...'pqrst'].map(ch).join('')}</div><div class=row>${SGN()}</div><div class=row>${bs(TM,'ldF')}</div><input id=sf2 placeholder="Second formula (compare)"><div class=row><button class=on onclick="sT()">Table · class · CNF</button><button onclick="sC()">Equivalent?</button></div></div><div id=out></div><div class=card><h3>Soundness</h3><div class=row>${SGN()}</div><div class=row>${bs(B.entail.slice(0,14),'ldE')}</div><textarea id=sp rows=3 placeholder="Premises, one per line"></textarea><input id=sq placeholder="Conclusion" style="margin-top:6px"><div class=row><button class=on onclick="sE()">Check</button></div></div><div id=out2></div>`:
`<div class=card><h3>Formula</h3><input id=pf placeholder="∀x∃y p(x,y)"><div class=row>${SGP()}</div><div class=row>${['x','y','z','a','b','c','p(x,y)','q(x)','r(x)','L(x,y)'].map(ch).join('')}${['∀x','∀y','∃x','∃y'].map(ch).join('')}</div><div class=row>${bs(TQ,'ldQ')}</div><input id=pf2 placeholder="Second formula (compare)"></div><div class=card><h3>Interpretation</h3><textarea id=pm rows=3>${MM[0]}</textarea><div class=row>${MM.map((_,i)=>`<button onclick="$('#pm').value=MM[${i}]">Model ${i+1}</button>`).join('')}<button onclick="$('#pm').value=rmodel()">🎲</button></div><div class=row><button class=on onclick="sP()">Evaluate</button><button onclick="sQ()">Equivalent?</button></div></div><div id=out></div>`}
const ldF=i=>{$('#sf').value=TM[i][1];sT()},ldQ=i=>{$('#pf').value=TQ[i][1];sP()},ldE=i=>{let e=B.entail[i];$('#sp').value=e[1].join('\n');$('#sq').value=e[2];sE()};
function sC(){out(()=>{let a=parse($('#sf').value),b=parse($('#sf2').value),w=eqv(a,b);return w?`<b class=no>Not equivalent</b> · differ at <code>${ist(w)}</code>`+tbl(vsOf([a,b]),[a,b],I=>ev(a,I)!=ev(b,I)):'<b class=ok>Equivalent</b>'+tbl(vsOf([a,b]),[a,b])})}
function sP(){out(()=>{let f=parse($('#pf').value,1),M=pint($('#pm').value);return mview(M)+pres(f,M)})}
function sQ(){out(()=>{let a=parse($('#pf').value,1),b=parse($('#pf2').value,1),w=peq(a,b);return w?'<b class=no>Not equivalent</b> · see model<br>'+mview(w)+'yours '+pev(a,w)+' · other '+pev(b,w):'<b class=ok>No counterexample found</b>'+eqNote()})}
