function ndLoad(i,c){let X=NDX[S.d],n=X.length,Y=c||X[((i%n)+n)%n];S.ndi=c?-1:((i%n)+n)%n;S.sg=[];S.nd={P:Y[0],G:Y[1],L:Y[0].map(f=>({f,r:'Premise',n:'',d:0,fx:1})),d:0,res:null,done:0,pd:S.d};ndShow()}
function nd(){if(!S.nd||S.nd.pd!=S.d)ndLoad(0);else ndShow()}
function ndShow(){const n=S.nd,X=NDX[S.d];n.pd=S.d;$('#M').innerHTML=`<div class=row>${X.map((_,i)=>`<button class="pl ${SV.solved[S.d+i]?'T':i==S.ndi?'on':''}" onclick="ndLoad(${i})">${i+1}</button>`).join('')}</div><div class=card><div class=f>{ ${n.P.join(',  ')} } ⊢ ${n.G}</div>${n.done?(n.sol?'<p class=ok>Solution shown — no points. Try the next one yourself!</p>':'<p class=ok>🎉 Proof complete! +10 ⭐</p>'):''}`+n.L.map((l,i)=>`<div class=ln style="margin-left:${l.d*18}px;${l.r=='Assume'?'border-color:var(--no)':''}"><b>${i+1}</b> <span class=f>${l.f}</span> <i class=mu>${l.r} ${l.n}</i> ${n.res?(n.res[i]===null?'<span class=ok>✓</span>':'<span class=no>✗ '+n.res[i]+'</span>'):''}</div>`).join('')+`<div class=row style="margin-top:8px"><input id=ndf placeholder="formula" style="flex:2"><select id=ndr>${RU[S.d].map(r=>`<option>${r}</option>`).join('')}</select><input id=ndn placeholder="refs 1,2 · 3-5" style="flex:1"></div><div class=row><button class=on onclick="ndAdd()">+ Line</button><button onclick="ndAdd(1)">▢ Assume</button><button onclick="if(S.nd.d>0){S.nd.d--;S.nd.cb=(S.nd.cb|0)+1}ndShow()">Close box</button><button onclick="ndUndo()">Undo</button><button onclick="ndChk()">Check</button><button onclick="ndHint()">Goal tip</button><button onclick="ndSug()">Suggest</button>${SOL[S.d][S.ndi]?'<button onclick="ndSol()">Solution</button>':''}</div><div id=hn></div><span class=mu>box depth ${n.d}</span></div><details class=card><summary>Rules</summary><div class=g>${RU[S.d].map(r=>`<div>${pl(r)}<br><span class=mu>${SC[r]}</span></div>`).join('')}</div></details><details class=card><summary>Custom sequent</summary><input id=cp placeholder="premises separated by ;"><input id=cg placeholder="goal" style="margin-top:6px"><div class=row><button onclick="ndLoad(0,[$('#cp').value.split(';').map(s=>s.trim()),$('#cg').value])">Load</button></div></details>`;pal()}
function ndSol(){const n=S.nd;n.sol=1;n.L=n.L.filter(l=>l.fx);SOL[S.d][S.ndi].forEach(([f,r,x,d])=>n.L.push({f,r,n:x,d}));n.d=0;ndChk()}
function ndSug(){const n=S.nd,pr=S.d=='pred',L=n.L,k=L.length,vis=j=>{for(let m=j+1;m<k;m++)if(L[m].d<L[j].d)return 0;return 1},F=L.map(l=>parse(l.f,pr)),have=new Set(F.filter((_,j)=>vis(j)).map(sh)),o=[],T=new Set;F.forEach(f=>targs(f,T));const bv=(f,s=new Set)=>{if(f.t=='q'){s.add(f.v);bv(f.a,s)}else if(f.t=='n')bv(f.a,s);else if(f.l){bv(f.l,s);bv(f.r,s)}return s};F.forEach(f=>bv(f).forEach(v=>T.delete(v)));
const add=(f,r,x)=>{let s=sh(f);if(!have.has(s)&&!o.some(q=>q[0]==s)&&o.length<8)o.push([s,r,x])};
F.forEach((a,i)=>{if(!vis(i))return;if(a.t=='a'){add(a.l,'∧E',i+1);add(a.r,'∧E',i+1)}if(a.t=='q'&&a.k=='A')T.forEach(t=>add(subst(a.a,a.v,t),'∀E',i+1));
F.forEach((b,j)=>{if(!vis(j))return;if(a.t=='i'&&eq0(a.l,b))add(a.r,'→E',(i+1)+','+(j+1));if(a.t=='i'&&b.t=='n'&&eq0(b.a,a.r))add({t:'n',a:a.l},'MT',(i+1)+','+(j+1));if(i!=j&&j>i&&0)add(b,'',0)})});
S.sg=o;$('#hn').innerHTML='<p>'+(o.length?o.map((x,i)=>`<button class=pl onclick="ndFill(${i})">${x[0]} <i>${x[1]}</i></button>`).join(' '):'No one-step moves: try ▢ Assume or work backwards from the goal.')+'</p>'}
const eq0=(a,b)=>sh(a)==sh(b);function ndFill(i){let[f,r,x]=S.sg[i];$('#ndf').value=f;$('#ndr').value=r;$('#ndn').value=x}
function ndChk(){const n=S.nd,pr=S.d=='pred',G=sh(parse(n.G,pr));n.res=n.L.map((_,i)=>ck(n.L,i,pr));let was=SV.solved[S.d+S.ndi];n.done=n.res.every(x=>x===null)&&n.L.some(l=>l.d==0&&sh(parse(l.f,pr))==G);if(n.done&&!was&&!n.sol&&S.ndi>=0){SV.solved[S.d+S.ndi]=1;addXP(10)}ndShow()}
