const WP=['p∧¬q→r','¬(p∧q)','(p→q)∧p','¬p∨q∧r','(p∨q)∧¬r','p→(q→r)','¬(p∨q)→r','(p∧q)∨¬r','p∨q→¬r','(p→q)→¬p','¬(p→q)','(p↔q)∧r'],
WQ=[['∀x(p(x)→q(x))','All p are q'],['∃x(p(x)∧q(x))','Some p is q'],['¬∃x(p(x)∧q(x))','No p is q'],['∀x∃yr(x,y)','Everyone relates to someone'],['∃x∀yr(x,y)','Someone relates to everyone'],['¬∀x(p(x)→q(x))','Not all p are q'],['∀x(p(x)→∃yr(x,y))','Every p relates to something']];
const WK={prop:['p','q','r','¬','∧','∨','→','↔','(',')'],pred:['p','q','r','x','y','∀','∃','¬','∧','∨','→','(',')',',']};
const wp=s=>parse([...s].join(' '),S.d=='pred');
WP.push('p∧¬q','¬p∨q','p→q∧r','p↔¬q','(p→q)∧(q→r)','¬(p∧q)↔¬p∨¬q','(p→q)∧¬q→¬p','p∨(q∧r)→(p∨q)∧r');WQ.push(['∀xp(x)','Everything is p'],['∃xq(x)','Something is q'],['¬∃xp(x)','Nothing is p'],['∃x(p(x)∧∀yr(x,y))','Some p relates to everything']);
const SGN=()=>['¬','∧','∨','→','↔','(',')'].map(ch).join('')+'<button class=pl onclick="last&&(last.value=\'\')">clear</button>',SGP=()=>['¬','∧','∨','→','↔','∀','∃','(',')',','].map(ch).join('')+'<button class=pl onclick="last&&(last.value=\'\')">clear</button>';
S.lv=1;
function wFb(g,s){let r=g.map(()=>'x'),u=[...s];g.forEach((c,i)=>{if(c==s[i]){r[i]='g';u[i]=null}});g.forEach((c,i)=>{if(r[i]!='g'){let j=u.indexOf(c);if(j>=0){r[i]='y';u[j]=null}}});return r}
function wNew(){let b=(S.d=='prop'?WP.map(s=>[s,'']):WQ),T=b0=>{let n=[...b0].length;return S.d=='prop'?(n<=6?0:n<=9?1:2):(n<=9?0:n<=13?1:2)},pool=b.filter(x=>T(x[0])==S.lv);b=pick(pool.length?pool:b);S.w={s:[...b[0]],c:b[1],g:[],cur:[],kb:{},h:[],done:0,msg:'',pd:S.d};wShow()}
function wKey(c){const w=S.w;if(w.done)return;if(c=='⌫')w.cur.pop();else if(c=='↵')return wGo();else if(w.cur.length<w.s.length){w.cur.push(c);w.pop=1}w.msg='';wShow()}
function wGo(){const w=S.w,N=w.s.length;if(w.cur.length<N){w.msg='Need '+N+' symbols';w.shake=1;return wShow()}let g=w.cur.join(''),f;try{f=wp(g)}catch(e){w.msg='Not a well-formed formula: '+e.message;w.shake=1;return wShow()}
const r=wFb(w.cur,w.s);w.g.push([[...w.cur],r]);w.fresh=1;r.forEach((x,i)=>{let c=w.cur[i],o={g:3,y:2,x:1};if(o[x]>(o[w.kb[c]]||0))w.kb[c]=x});
if(g==w.s.join('')){w.done=1;w.win=1;w.msg='🎉 Cracked in '+w.g.length+'!';SV.wins++;SV.streak++;addXP((7-w.g.length)*(S.lv+1)*2)}else{try{let q=wp(w.s.join(''));if(S.d=='prop'?!eqv(f,q):!peq(f,q))w.msg='So close: equivalent to the secret, but not the same formula!'}catch(e){}if(w.g.length>=6){w.done=1;SV.streak=0;sv();w.msg='💀 Out of tries. It was '+w.s.join('')}}
w.cur=[];wShow()}
function wHint(){const w=S.w;if(w.done)return;if(SV.xp<3){w.msg='Need 3 ⭐ for a hint';return wShow()}let o=w.s.map((_,i)=>i).filter(i=>!w.h.includes(i)&&!w.g.some(([a,r])=>r[i]=='g'));if(!o.length)return;w.h.push(pick(o));SV.xp-=3;sv();w.msg='💡 A ghost symbol appears in your row (−3 ⭐)';nav();wShow()}
function wShare(){const w=S.w;let t='Symbolix '+(w.win?w.g.length:'X')+'/6\n'+w.g.map(([a,r])=>r.map(x=>({g:'🟩',y:'🟨',x:'⬛'})[x]).join('')).join('\n');try{navigator.clipboard.writeText(t);w.msg='📋 Copied!'}catch(e){w.msg=t}wShow()}
function wShow(){if(!S.w||S.w.pd!=S.d){wNew();return}const w=S.w,N=w.s.length,last=w.g.length-1;
const row=(a,r,fl,cur)=>`<div class="wr ${cur&&w.shake?'shake':''}">${Array.from({length:N},(_,i)=>`<div class="tl ${r?r[i]:''} ${fl?'flip':''} ${cur&&a[i]?'fl':''} ${cur&&!a[i]&&w.h.includes(i)?'hint':''} ${cur&&w.pop&&i==a.length-1?'pop':''}" style="${fl?'animation-delay:'+i*.22+'s':''}">${a[i]||(cur&&w.h.includes(i)?w.s[i]:'')}</div>`).join('')}</div>`;
let clue;if(S.d=='prop'){let f=wp(w.s.join('')),vs=vsOf([f]);clue='<div class=sc><table><tr>'+vs.map(v=>'<th>'+v).join('')+'<th>?</tr>'+rows(vs).map(I=>'<tr>'+vs.map(v=>'<td>'+(I[v]?'T':'F')).join('')+'<td class='+(ev(f,I)?'T':'F')+'>'+(ev(f,I)?'T':'F')+'</tr>').join('')+'</table></div>'}else clue='<div class=big>“'+w.c+'”</div>';
const lvl=Math.floor(SV.xp/50)+1,cf=w.win&&w.fresh?Array.from({length:26},()=>`<span class=cf style="left:${Math.random()*100}vw;animation-delay:${Math.random()}s">${pick(['🎉','✨','∀','∃','¬','→','🟩'])}</span>`).join(''):'';
$('#M').innerHTML=`<div class=gm>${cf}<div class=lg>SYMBOLIX</div><div class=mu>crack the hidden ${S.d=='prop'?'formula from its truth table':'formula from its meaning'}</div><div class=gs><span>Lv ${lvl}</span><div class=bar><i style="width:${SV.xp%50*2}%"></i></div><span>🔥 ${SV.streak}</span><span>🏆 ${SV.wins}</span></div><div class=row>${['Easy','Normal','Hard'].map((l,i)=>`<button class="pl ${S.lv==i?'on':''}" onclick="S.lv=${i};wNew()">${l}</button>`).join('')}<span style="margin-left:auto">${'❤️'.repeat(6-w.g.length)}${'🖤'.repeat(w.g.length)}</span></div><div class=clue>${clue}</div>${w.g.map(([a,r],i)=>row(a,r,w.fresh&&i==last)).join('')}${w.done?'':row(w.cur,0,0,1)}${Array.from({length:Math.max(0,5-w.g.length)},()=>row([])).join('')}<p class=${w.win?'ok':'bad'}>${w.msg}</p><div class=row style="justify-content:center">${WK[S.d].map(c=>`<button class="kb ${w.kb[c]||''}" onclick="wKey('${c}')">${c}</button>`).join('')}<button class=kb onclick="wKey('⌫')">⌫</button><button class="kb ent" onclick="wKey('↵')">ENTER</button></div><div class=row style="justify-content:center"><button class=pl onclick="wHint()">💡 Hint −3⭐</button><button class=pl onclick="wNew()">🎲 New</button>${w.done?'<button class=pl onclick="wShare()">📋 Share</button>':''}</div></div>`;w.fresh=w.shake=w.pop=0}
function wd(){wShow()}

addEventListener('keydown',e=>{if(S.m!='wd'||/INPUT|TEXTAREA/.test(e.target.tagName))return;let k=e.key=='Enter'?'↵':e.key=='Backspace'?'⌫':e.key;if(WK[S.d].includes(k)||k=='↵'||k=='⌫')wKey(k)});

const LS=[
{r:'∧I',t:'Introduce ∧ (glue)',P:['p','q'],G:'p∧q',h:'The goal is A∧B: prove both parts, then glue them.',S:[['p∧q','∧I','1,2',0,'We already have p (line 1) and q (line 2). ∧I glues two proven facts into one conjunction.']]},
{r:'∧E',t:'Eliminate ∧ (take a side)',P:['p∧q'],G:'q∧p',h:'A premise A∧B can be split into A and B.',S:[['q','∧E','1',0,'A conjunction is true only if both sides are, so the right side q can be taken out.'],['p','∧E','1',0,'The left side p comes out the same way.'],['q∧p','∧I','2,3',0,'Now glue them in the new order with ∧I. Rules combine: split, then rebuild.']]},
{r:'∨I',t:'Introduce ∨ (widen)',P:['p'],G:'p∨q',h:'To prove A∨B it is enough to prove one side.',S:[['p∨q','∨I','1',0,'p is true, so "p or anything" is true. q does not need to be proven!']]},
{r:'→E',t:'Eliminate → (modus ponens)',P:['p→q','p'],G:'q',h:'You have A→B and A: you get B.',S:[['q','→E','1,2',0,'Line 1 says "if p then q", line 2 gives p. So q follows.']]},
{r:'MT',t:'Modus tollens',P:['p→q','¬q'],G:'¬p',h:'You have A→B and ¬B: you get ¬A.',S:[['¬p','MT','1,2',0,'If p were true, q would be too (line 1). But q is false (line 2), so p must be false.']]},
{r:'→I',t:'Introduce → (assume and discharge)',P:['p→q','q→r'],G:'p→r',h:'The goal is A→B: assume A in a box, prove B, close the box.',S:[['p','Assume','',1,'The goal is an implication. Open a box and ASSUME its left side p. Inside the box p is a temporary fact.'],['q','→E','1,3',1,'Inside the box we may use p. Line 1 (p→q) and p give q.'],['r','→E','2,4',1,'Line 2 (q→r) and q give r. We reached the right side of the goal.'],['p→r','→I','3-5',0,'Close the box: "if p, then r". The assumption is discharged, so the line sits outside the box. Refs use a range 3-5.']]},
{r:'∨E',t:'Eliminate ∨ (cases)',P:['p∨q','p→r','q→r'],G:'r',h:'A premise A∨B: prove the goal assuming A, then assuming B.',S:[['p','Assume','',1,'Line 1 says p or q. Case 1: assume p in a box.'],['r','→E','2,4',1,'In case 1: p→r and p give r.'],['q','Assume','',1,'Case 2: a new box, assume q.'],['r','→E','3,6',1,'In case 2: q→r and q give r. Both cases reach the SAME formula r.'],['r','∨E','1,4-5,6-7',0,'∨E needs the disjunction (1) and both boxes (4-5, 6-7). r holds whichever case is true.']]},
{r:'¬I',t:'Introduce ¬ (refute)',P:['p→q','p→¬q'],G:'¬p',h:'The goal is ¬A: assume A and reach a contradiction.',S:[['p','Assume','',1,'To prove ¬p, assume p in a box and look for a contradiction.'],['q','→E','1,3',1,'From p→q and p we get q.'],['¬q','→E','2,3',1,'From p→¬q and p we get ¬q.'],['q∧¬q','∧I','4,5',1,'q and ¬q together: a contradiction, written X∧¬X.'],['¬p','¬I','3-6',0,'Assuming p led to a contradiction, so p is impossible: ¬p.']]},
{r:'¬E',t:'Reductio ad absurdum',P:['¬p→q','¬p→¬q'],G:'p',h:'The goal is A (not negated, no better rule): assume ¬A and reach a contradiction.',S:[['¬p','Assume','',1,'Assume the opposite of the goal.'],['q','→E','1,3',1,'Line 1 and the assumption give q.'],['¬q','→E','2,3',1,'Line 2 and the assumption give ¬q.'],['q∧¬q','∧I','4,5',1,'Contradiction.'],['p','¬E','3-6',0,'¬p is impossible, so p holds. (Difference with ¬I: here we conclude the un-negated formula.)']]},
{r:'¬¬E',t:'Remove double negation',P:['¬¬p'],G:'p',h:'¬¬A gives A.',S:[['p','¬¬E','1',0,'Two negations cancel.']]},
{r:'↔I',t:'Introduce ↔',P:['p→q','q→p'],G:'p↔q',h:'To prove A↔B, prove A→B and B→A.',S:[['p↔q','↔I','1,2',0,'Both directions are proven (lines 1 and 2), so the biconditional holds.']]},
{r:'↔E',t:'Eliminate ↔',P:['p↔q','p'],G:'q',h:'A↔B plus one side gives the other side.',S:[['q','↔E','1,2',0,'p and q have the same truth value; p is true, so q is too.']]},
{r:'∀E',pr:1,t:'Eliminate ∀ (instantiate)',P:['∀x(p(x)→q(x))','p(a)'],G:'q(a)',h:'∀xF lets you replace x by any term, such as a constant from the problem.',S:[['p(a)→q(a)','∀E','1',0,'The premise holds for every x, in particular x = a.'],['q(a)','→E','3,2',0,'Now it is plain modus ponens with p(a) (line 2).']]},
{r:'∃I',pr:1,t:'Introduce ∃ (witness)',P:['p(a)'],G:'∃x p(x)',h:'Show a concrete example, then ∃I.',S:[['∃x p(x)','∃I','1',0,'p(a) is true, so something satisfies p: a is the witness.']]},
{r:'∀I',pr:1,t:'Introduce ∀ (fresh name)',P:['∀x(p(x)∧q(x))'],G:'∀x p(x)',h:'To prove ∀xF, prove F for a NEW name c that appears nowhere above.',S:[['p(c)∧q(c)','∀E','1',0,'Pick a brand new name c (not in any premise) and instantiate line 1.'],['p(c)','∧E','2',0,'Take out p(c).'],['∀x p(x)','∀I','3',0,'c was arbitrary (nothing special about it), so p holds for all x.']]},
{r:'∃E',pr:1,t:'Eliminate ∃ (name the witness)',P:['∃x p(x)','∀x(p(x)→q(x))'],G:'∃x q(x)',h:'A premise ∃xF: assume F for a NEW name c in a box; the conclusion must not mention c.',S:[['p(c)','Assume','',1,'Line 1 says some x has p. Give it a new name c and assume p(c) in a box.'],['p(c)→q(c)','∀E','2',1,'Instantiate line 2 with c.'],['q(c)','→E','4,3',1,'Modus ponens.'],['∃x q(x)','∃I','5',1,'Inside the box, build the goal with ∃I (c is the witness).'],['∃x q(x)','∃E','1,3-6',0,'The goal does not mention c, so it can leave the box. ∃E refs: the ∃ line, then the box.']]},
{r:'Combo',t:'Putting it together',P:['p→q','r→s','p∨r'],G:'q∨s',h:'Goal ∨ and a premise ∨: use cases (∨E) and finish each case with ∨I.',S:[['p','Assume','',1,'A premise is p∨r, so split into cases. Case 1: assume p.'],['q','→E','1,4',1,'p→q gives q.'],['q∨s','∨I','5',1,'Widen to the goal q∨s.'],['r','Assume','',1,'Case 2: assume r.'],['s','→E','2,7',1,'r→s gives s.'],['q∨s','∨I','8',1,'Widen to the goal again.'],['q∨s','∨E','3,4-6,7-9',0,'Both cases end in q∨s, so q∨s follows from p∨r.']]}];
function ls(){S.ls=S.ls||0;S.st=S.st||0;if(S.d=='prop'&&LS[S.ls].pr)S.ls=0;lsShow()}
function lsShow(){const Q=LS[S.ls],k=S.st,n=Q.S.length,lines=Q.P.map(f=>({f,r:'Premise',n:'',d:0})).concat(Q.S.slice(0,k).map(s=>({f:s[0],r:s[1],n:s[2],d:s[3]}))),cur=k?Q.S[k-1]:null,rf=cur?(cur[2].match(/\d+/g)||[]).map(Number):[];
$('#M').innerHTML=`<div class=row>${LS.map((l,i)=>l.pr&&S.d=='prop'?'':`<button class="pl ${i==S.ls?'on':''}" onclick="S.ls=${i};S.st=0;lsShow()">${l.r}</button>`).join('')}</div><div class=card><h3>${Q.r} · ${Q.t}</h3>${SC[Q.r]?pl(SC[Q.r]):''}<div class=f style="margin:8px 0">{ ${Q.P.join(',  ')} } ⊢ ${Q.G}</div>`+lines.map((l,i)=>`<div class=ln style="margin-left:${l.d*18}px;${l.r=='Assume'?'border-color:var(--no);':''}${i==lines.length-1&&k?'background:color-mix(in srgb,var(--ok) 18%,transparent);':''}${rf.includes(i+1)?'outline:2px solid var(--ac);':''}"><b>${i+1}</b> <span class=f>${l.f}</span> <i class=mu>${l.r} ${l.n}</i></div>`).join('')+`<div class=card style="margin:10px 0 0">${k?`<b>Step ${k}/${n} · ${cur[1]}${cur[2]?' on '+cur[2]:''}</b><br>${cur[4]}${k==n?'<p class=ok>✅ Goal reached!</p>':''}`:`Premises are given: we may use them at any time.<br><b>Goal:</b> ${Q.G}<br>💡 ${Q.h}`}</div><div class=row style="margin-top:8px"><button onclick="S.st=Math.max(0,S.st-1);lsShow()">◀ Back</button><button class=on onclick="${k<n?'S.st++':'S.st=0'};lsShow()">${k<n?'Next ▶':'↺ Restart'}</button><button onclick="lsAuto()">⏵ Auto</button><button onclick="S.m='nd';S.d='${Q.pr?'pred':S.d}';ndLoad(0,[LS[${S.ls}].P,LS[${S.ls}].G]);nav()">✍️ Try it yourself</button></div><div>${Array.from({length:n+1},(_,i)=>`<span class="dot ${i<=k?'T':''}" style="min-width:12px;height:12px"></span>`).join('')}</div></div>`}
function lsAuto(){clearInterval(S.ap);S.st=0;lsShow();S.ap=setInterval(()=>{if(S.m!='ls'||S.st>=LS[S.ls].S.length){clearInterval(S.ap);return}S.st++;lsShow()},2600)}

function loc(n,V){const g=m=>m?V[m.id]:undefined,v=V[n.id],a=n.t=='n'?g(n.a):g(n.l),b=g(n.r),o=[],T=true,F=false;
switch(n.t){case'n':if(v!==undefined)o.push([n.a,!v,'¬ flips the value']);if(a!==undefined)o.push([n,!a,'¬ flips the value']);break;
case'a':if(v===T)o.push([n.l,T,'a true ∧ needs both true'],[n.r,T,'a true ∧ needs both true']);if(v===F&&a===T)o.push([n.r,F,'∧ is false and the left is true']);if(v===F&&b===T)o.push([n.l,F,'∧ is false and the right is true']);if(a===F||b===F)o.push([n,F,'a conjunct is false']);if(a===T&&b===T)o.push([n,T,'both sides true']);break;
case'o':if(v===F)o.push([n.l,F,'a false ∨ needs both false'],[n.r,F,'a false ∨ needs both false']);if(v===T&&a===F)o.push([n.r,T,'∨ is true and the left is false']);if(v===T&&b===F)o.push([n.l,T,'∨ is true and the right is false']);if(a===T||b===T)o.push([n,T,'a disjunct is true']);if(a===F&&b===F)o.push([n,F,'both sides false']);break;
case'i':if(v===F)o.push([n.l,T,'a false → means T → F'],[n.r,F,'a false → means T → F']);if(v===T&&a===T)o.push([n.r,T,'→ is true and the left is true']);if(v===T&&b===F)o.push([n.l,F,'→ is true and the right is false']);if(a===F||b===T)o.push([n,T,'false antecedent or true consequent']);if(a===T&&b===F)o.push([n,F,'T → F is false']);break;
case'e':if(v===T&&a!==undefined)o.push([n.r,a,'↔ true: same value']);if(v===T&&b!==undefined)o.push([n.l,b,'↔ true: same value']);if(v===F&&a!==undefined)o.push([n.r,!a,'↔ false: opposite values']);if(v===F&&b!==undefined)o.push([n.l,!b,'↔ false: opposite values']);if(a!==undefined&&b!==undefined)o.push([n,a==b,'compare both sides'])}return o}
function prove(F){let id=0;const N=[];(function w(n){n.id=id++;N[n.id]=n;if(n.t=='n')w(n.a);else if(n.l){w(n.l);w(n.r)}})(F);
const V={},L=[];let cex=null;const lg=(txt,d,k)=>L.push({txt,d,k,V:{...V}}),
set=(n,v,why,d)=>{if(V[n.id]!==undefined){if(V[n.id]!==v){lg('✗ '+sh(n,0)+' would be both T and F: CONTRADICTION',d,'x');return'X'}return 0}V[n.id]=v;if(n.t=='v')N.forEach(m=>{if(m.t=='v'&&m.n==n.n&&V[m.id]===undefined)V[m.id]=v});lg(sh(n,0)+' = '+(v?'T':'F')+(why?'  — '+why:''),d,'s');return 1},
prop=d=>{let ch=1;while(ch){ch=0;for(const n of N)for(const[m,v,w]of loc(n,V)){let r=set(m,v,w,d);if(r=='X')return'X';if(r)ch=1}}return 0},
solve=d=>{if(prop(d)=='X')return'X';const u=N.find(n=>n.t=='v'&&V[n.id]===undefined);if(!u){cex={};N.forEach(n=>{if(n.t=='v'&&n.n!='⊤'&&n.n!='⊥')cex[n.n]=V[n.id]});return'C'}
for(const v of[true,false]){const s0={...V};lg('Case '+u.n+' = '+(v?'T':'F'),d,'c');let r=set(u,v,'case split',d+1);if(r!='X')r=solve(d+1);if(r=='C')return'C';Object.keys(V).forEach(k=>delete V[k]);Object.assign(V,s0)}return'X'};
N.filter(n=>n.t=='v'&&(n.n=='⊤'||n.n=='⊥')).forEach(n=>set(n,n.n=='⊤','constant',0));const r0=set(F,false,'assume the formula is FALSE',0);const r=r0=='X'?'X':solve(0);lg(r=='X'?'Every case ends in a contradiction ⇒ the formula is VALID':'No contradiction: '+ist(cex)+' makes it false ⇒ NOT valid',0,'f');return{L,valid:r=='X',cex,F}}
const tv=(n,V)=>{const v=V[n.id],k=n.t=='n'?[n.a]:n.l?[n.l,n.r]:[];return`<span class=nb><b class="vb ${v===undefined?'':v?'T':'F'}">${v===undefined?'?':v?'T':'F'}</b><br>${n.t=='v'?n.n:OP[n.t]||'¬'}<br>${k.map(c=>tv(c,V)).join('')}</span>`};
const CX=[...B.entail.slice(0,8).map(e=>[e[0],e[1],e[2]]),...B.class.slice(0,5).map((f,i)=>['Formula '+(i+1),[],f])];
function ct(){if(S.d=='pred'){$('#M').innerHTML=cv('Proof by contradiction','Available in propositional logic. For predicate logic use the Deduction tab.');return}
$('#M').innerHTML=`<div class=card><h3>Proof by contradiction</h3><span class=mu>Assume it is false, propagate, split into cases.</span><div class=row>${SGN()}</div><textarea id=cp rows=2 placeholder="Premises (optional), one per line"></textarea><input id=cq placeholder="Formula, or conclusion if premises given" style="margin-top:6px"><div class=row>${CX.map((x,i)=>`<button onclick="ldC(${i})">${x[0]}</button>`).join('')}</div><div class=row><button class=on onclick="ctRun()">Prove</button></div></div><div id=ctout></div>`}
function ldC(i){$('#cp').value=CX[i][1].join('\n');$('#cq').value=CX[i][2];ctRun()}
function ctRun(){try{let ps=$('#cp').value.split('\n').filter(x=>x.trim()).map(x=>parse(x)),q=parse($('#cq').value),F=ps.length?{t:'i',l:ps.reduce((a,b)=>({t:'a',l:a,r:b})),r:q}:q;S.ct=prove(F);S.ctk=1;ctShow()}catch(e){$('#ctout').innerHTML='<div class=card><span class=no>'+e.message+'</span></div>'}}
function ctShow(){const c=S.ct,k=S.ctk,n=c.L.length,s=c.L[k-1];$('#ctout').innerHTML=`<div class=card><b>${sh(c.F)}</b><div class=sc style="margin:8px 0">${tv(c.F,s.V)}</div>`+c.L.slice(0,k).map((x,i)=>`<div class=ln style="margin-left:${x.d*16}px;${x.k=='x'?'border-color:var(--no);':x.k=='c'?'border-color:var(--ok);':''}${i==k-1?'background:color-mix(in srgb,var(--ok) 16%,transparent);':''}">${x.k=='c'||x.k=='f'?'<b>'+x.txt+'</b>':x.txt}</div>`).join('')+(k==n?`<p class=${c.valid?'ok':'no'}>${c.valid?'✅ VALID ⇒ the reasoning is SOUND':'❌ NOT valid ⇒ the reasoning is NOT sound'}</p>`:'')+`<div class=row><button onclick="S.ctk=Math.max(1,S.ctk-1);ctShow()">◀ Back</button><button class=on onclick="S.ctk=${k<n?'S.ctk+1':'1'};ctShow()">${k<n?'Next ▶':'↺ Restart'}</button><button onclick="S.ctk=${n};ctShow()">Show all</button></div><span class=mu>Step ${k}/${n}</span></div>`}

function tctInit(){const e=$('#tctx');if(!e)return;e.innerHTML=`<div class=g>${[['1','Assume the formula is FALSE'],['2','Propagate T/F through ¬ ∧ ∨ → ↔'],['3','One atom both T and F? Contradiction'],['4','All cases contradict ⇒ VALID. One survives ⇒ counterexample']].map(x=>rw(...x)).join('')}</div><div class=row><button class=on onclick="tctEx(0)">Valid example</button><button onclick="tctEx(1)">Not valid example</button><button onclick="S.m='ct';go()">Open the Contradiction tab →</button></div><div id=ctout></div>`;tctEx(0)}
function tctEx(i){S.ct=prove(parse(['(p→q)∧p→q','(p→q)∧q→p'][i]));S.ctk=1;ctShow()}
go()
